insert into Ojegov (id, word, explanation) values (9, 'абазины', '-ин, ед. -инец, -нца, м. Народ, живущий в Карачаево-Черкесии и в Адыгее. II ж. абазинка, -и. II прил, абазинский, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (10, 'абонент', '-а, м. Лицо, пользующееся абонементом, имеющее право на пользование чем-н. по абонементу. А. библиотеки. А. телефонной сети (лицо или учреждение, имеющее телефон). II ж. абонентка, -и (разг.). II прил. абонентский, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (11, 'абордаж', '-а, м. В эпоху гребного и парусного флота: атака корабля противника при непосредственном сближении с ним для рукопашного боя. Взять на а. (также перен.). II прил. абордажный, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (12, 'абразив', '-а, м. (спец.). Твердое мелкозернистое или порошкообразное вещество (кремень, наждак, корунд, карборунд, пемза, гранат), применяемое для шлифовки, полировки, заточки. II прил. абразивный, -ая, -ое. ');
insert into Ojegov (id, word, explanation) values (13, 'абрикос', '-а,род.мн. -ов,м. Южное фруктовое дерево сем. розоцветных, дающее сочные сладкие плоды с крупной косточкой, а также плод его. II прил. абрикосный, -ая, -ое ы абрикосовый, oая, -ое.');
insert into Ojegov (id, word, explanation) values (14, 'абсолют', '-а, м. (книжн.). 1. В философии: вечная, неизменная первооснова всего существующего (дух, идея, божество). 2. Нечто самодовлеющее, независимое от каких-н. условий и отношений. Возвести что-н. в а.');
insert into Ojegov (id, word, explanation) values (15, 'абсцесс', '-а, м. (спец.). Нарыв, гнойник, скопление гноя в органах или тканях в результате воспалительного процесса. II прил. абсцессный, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (16, 'аванзал', '-а, м. Помещение перед главным залом в общественных зданиях. II прил. аванзальный, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (17, 'авансом', 'нареч. В качестве аванса; вперед, заранее. Получить а. сто рублей. Поощрить а. (разг.).');
insert into Ojegov (id, word, explanation) values (18, 'авиатор', '-а, м. Специалист по управлению, вождению и обслуживанию летательных аппаратов. II прил. авиаторский, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (28, 'авиация', '-и, ж. 1. Теория и практика передвижения по воздуху на летательных аппаратах тяжелее воздуха. 2. Воздушные средства передвижения, воздушный флот. Гражданская а. Военная а. II прил. авиационный, -ая, -ое,');
insert into Ojegov (id, word, explanation) values (19, 'авоська', '-и, ж. (разг.). То же, что сетка (во 2 знач.).');
insert into Ojegov (id, word, explanation) values (20, 'автобус', '-а, м. Многоместный автомобиль для перевозки пассажиров. Городской а. Служебный а. II прил. автобусный, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (21, 'автоген', '-а, м. Автогенная сварка, резка.');
insert into Ojegov (id, word, explanation) values (22, 'автокар', '-a, м. Самодвижущаяся тележка с двигателем внутреннего сгорания для безрельсовой перевозки грузов. II прил. автокарный, oая, oое.');
insert into Ojegov (id, word, explanation) values (23, 'автомат', '-а, м. 1. ');
insert into Ojegov (id, word, explanation) values (24, 'аграрий', '-я,м. 1. Политик, представляю-щий интересы агропромышленного комплекса (разг.). 2. Крупный землевладелец, помещик (устар.).');
insert into Ojegov (id, word, explanation) values (25, 'агрегат', '-а, м. 1. Соединение для общей работы двух или нескольких разнотипных машин. Уборочный а. 2. Часть какой-н. машины, узел(в 3 знач.) для выполнения определенных операций. II прил. агрегатный, -ая, -ое.');
insert into Ojegov (id, word, explanation) values (26, 'агроном', '-a, м. Специалист по агрономии. II ж. агрономша, -и (прост.).');
insert into Ojegov (id, word, explanation) values (27, 'адвокат', '-а, м. Юрист, к-рому поручается оказание юридической помощи гражданам и организациям, в том числе защита чьих-н. интересов в суде, защитник. Коллегия адвокатов. II ж. адвокатесса [тэ], -ы (разг.) ');
